package com.rubidiumclient.module.combatimport com.rubidiumclient.core.proxy.EntityTrackerimport com.rubidiumclient.core.relay.RubidiumRelaySessionimport com.rubidiumclient.events.PacketEventimport com.rubidiumclient.events.PacketEventBusimport com.rubidiumclient.module.*import com.rubidiumclient.utils.InventoryUtilimport com.rubidiumclient.utils.MathUtilimport com.rubidiumclient.utils.PacketUtilimport com.rubidiumclient.utils.WorldBlockTrackerimport kotlinx.coroutines.*import org.cloudburstmc.math.vector.Vector3fimport org.cloudburstmc.math.vector.Vector3iimport org.cloudburstmc.protocol.bedrock.data.LevelEventimport org.cloudburstmc.protocol.bedrock.data.definitions.BlockDefinitionimport org.cloudburstmc.protocol.bedrock.data.definitions.SimpleBlockDefinitionimport org.cloudburstmc.protocol.bedrock.data.inventory.ItemDataimport org.cloudburstmc.protocol.bedrock.data.inventory.transaction.InventoryTransactionTypeimport org.cloudburstmc.protocol.bedrock.data.inventory.transaction.ItemUseTransactionimport org.cloudburstmc.protocol.bedrock.packet.*import java.util.concurrent.ConcurrentHashMapimport kotlin.math.floor/** * CrystalAura — multi-place + pre-warmed block cache sürümü. * * Önceki sürümdeki sorunlar: *  1. getBlockDefinition() her çağrıda 20.000-blok döngüsü çalıştırıyordu *     (hot-path'te catastrophic, her tick her yerleştirme için). *  2. Hardcoded runtimeId fallback (obsidian=49) Bedrock'ta server'a göre *     değiştiği için paket reject → "bazen çalışıyor bazen çalışmıyor". *  3. Tek kristal: prepareItemForUse() her kristal için çağrılıyordu *     (slot switch × N gereksiz paket). *  4. place/explode aynı delayMs'i paylaşıyordu. * * Düzeltmeler: *  • ensureBlockCacheWarmed(): palette'in tamamı onEnable'dan sonra ilk *    tick'te tek seferde taranıp ConcurrentHashMap'e yükleniyor. *    Sonraki tüm lookuplar O(1). Fallback kaldırıldı — cache'te yoksa *    yerleştirme yapılmıyor (yanlış runtimeId ile silently reject *    edilmekten iyidir). *  • tryPlaceBest(): prepareItemForUse() bir kez, N paket, hotbar *    revert bir kez. placeCount (varsayılan 4) pozisyon aynı tick'te *    yerleştiriliyor. *  • Ayrı placeDelayMs / explodeDelayMs. *  • Shortcut ayarı (FreeCamera ile aynı pattern). */class CrystalAura : BaseModule(    name        = "CrystalAura",    category    = ModuleCategory.COMBAT,    description = "Hasar simülasyonuna göre en iyi noktaya kristal yerleştirir/kırar") {    companion object {        private const val EXPLOSION_SIZE   = 6f        private const val TICK_INTERVAL_MS = 50L        private val NON_SOLID = setOf(            "minecraft:air", "minecraft:water", "minecraft:flowing_water",            "minecraft:lava", "minecraft:flowing_lava",            "minecraft:void_air", "minecraft:cave_air"        )    }    // ── Ayarlar ──────────────────────────────────────────────────────────    private val range           = float("Range",           5f,   3f,  10f)    private val suicide         = bool ("Suicide",         false)    private val place           = bool ("Place",           true)    private val placeCount      = int  ("PlaceCount",      4,    1,   8)    private val placeDelayMs    = int  ("PlaceDelay",      100,  50,  500)    private val explodeDelayMs  = int  ("ExplodeDelay",    50,   20,  300)    private val removeParticles = bool ("RemoveParticles", true)    private val shortcut        = bool ("Shortcut",        false)    // ── State ─────────────────────────────────────────────────────────────    @Volatile private var lastExplodeMs = 0L    @Volatile private var lastPlaceMs   = 0L    @Volatile private var cacheWarmed   = false    private var tickJob: Job? = null    // Block definition cache — ilk tick'te palette'ten doldurulur, sonrası O(1)    private val blockDefCache = ConcurrentHashMap<String, BlockDefinition>(512)    private data class ExplosionResult(val mostDamage: Float, val selfDamage: Float)    private data class PreparedItem(val slot: Int, val item: ItemData, val revertTo: Int?)    // ── Lifecycle ─────────────────────────────────────────────────────────    override fun onEnable() {        super.onEnable()        lastExplodeMs = 0L        lastPlaceMs   = 0L        cacheWarmed   = false        blockDefCache.clear()        PacketEventBus.register(this)        tickJob = scope.launch { tickLoop() }    }    override fun onDisable() {        tickJob?.cancel()        PacketEventBus.unregister(this)        super.onDisable()    }    // ── Packet handler ────────────────────────────────────────────────────    override fun onPacket(event: PacketEvent) {        if (!isEnabled) return        when (val pkt = event.packet) {            // Yeni doğan kristali anında patlat (tick bekleme olmadan).            is AddEntityPacket -> {                if (!pkt.identifier.contains("crystal", ignoreCase = true)) return                val now = System.currentTimeMillis()                if (now - lastExplodeMs < explodeDelayMs.value) return                val cx = pkt.position.x; val cy = pkt.position.y; val cz = pkt.position.z                if (MathUtil.dist3(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ) > range.value) return                val dmg = simulateExplosionDamage(cx, cy, cz)                if (dmg.selfDamage <= dmg.mostDamage || suicide.value) {                    val session = PacketEventBus.currentSession ?: return                    explodeCrystal(session, pkt.runtimeEntityId)                    lastExplodeMs = now                }            }            is LevelEventPacket -> {                if (removeParticles.value && pkt.type == LevelEvent.PARTICLE_EXPLOSION) event.cancel()            }            else -> {}        }    }    // ── Tick loop ─────────────────────────────────────────────────────────    private suspend fun tickLoop() {        while (currentCoroutineContext().isActive) {            if (isEnabled) tick()            delay(TICK_INTERVAL_MS)        }    }    private fun tick() {        val session = PacketEventBus.currentSession ?: return        // ① Block definition cache'ini ilk tick'te bir kez ısıt.        //    Sonraki tüm lookuplar ConcurrentHashMap'ten O(1).        // FIX: cacheWarmed artık sadece cache gerçekten dolduysa true oluyor.        // Öncesinde ensureBlockCacheWarmed() başarısız olsa bile (server henüz        // block palette göndermemişse — modül dünyaya girer girmez açılırsa        // çok olası) cacheWarmed koşulsuz true set ediliyordu, cache kalıcı        // boş kalıyordu ve sendPlacementUseRaw sonsuza dek false dönüyordu —        // "kristal koymuyor" ana sebebi buydu.        if (!cacheWarmed) {            ensureBlockCacheWarmed(session)            if (blockDefCache.isNotEmpty()) cacheWarmed = true        }        val now = System.currentTimeMillis()        if (now - lastExplodeMs >= explodeDelayMs.value) tryExplodeBest(session, now)        if (place.value && now - lastPlaceMs >= placeDelayMs.value) tryPlaceBest(session, now)    }    // ── Explode ───────────────────────────────────────────────────────────    private fun tryExplodeBest(session: RubidiumRelaySession, now: Long) {        val crystals = EntityTracker.getCrystals(range.value)        if (crystals.isEmpty()) return        var bestId: Long? = null        var bestDamage = -1f        for (c in crystals) {            val dmg = simulateExplosionDamage(c.x, c.y, c.z)            val effective = if (dmg.selfDamage > dmg.mostDamage && !suicide.value) -1f else dmg.mostDamage            if (effective > bestDamage) { bestDamage = effective; bestId = c.runtimeId }        }        if (bestId != null && bestDamage > 0f) {            explodeCrystal(session, bestId)            lastExplodeMs = now        }    }    // ── Multi-place ───────────────────────────────────────────────────────    //    // FIX: önceki sürümde prepareItemForUse() her kristal için çağrılıyordu    // (slot switch × N paket). Şimdi: bir kez prepare, N placement paketi,    // bir kez revert. Hem daha hızlı hem de daha az paket gürültüsü.    private fun tryPlaceBest(session: RubidiumRelaySession, now: Long) {        val bases = searchPlaceBase().toMutableList()        // Obsidian/bedrock yoksa rakip etrafındaki fallback pozisyonlar        if (bases.isEmpty()) {            for (target in EntityTracker.getPlayers(range.value)) {                if (target.runtimeId == EntityTracker.selfRuntimeId) continue                val tx = floor(target.x).toInt()                val ty = floor(target.y).toInt() - 1                val tz = floor(target.z).toInt()                for ((dx, dz) in listOf(0 to 1, 0 to -1, 1 to 0, -1 to 0, 1 to 1, 1 to -1, -1 to 1, -1 to -1)) {                    bases.add(Triple(tx + dx, ty, tz + dz))                }            }        }        if (bases.isEmpty()) return        // Tüm pozisyonları hasar skoruna göre sırala, en iyi placeCount tanesini al        val topPositions = bases            .mapNotNull { pos ->                val cx = pos.first + 0.5f                val cy = pos.second + 2f                val cz = pos.third + 0.5f                val dmg = simulateExplosionDamage(cx, cy, cz)                val eff = if (dmg.selfDamage > dmg.mostDamage && !suicide.value) -1f else dmg.mostDamage                if (eff > 0f) Pair(pos, eff) else null            }            .sortedByDescending { it.second }            .take(placeCount.value)        if (topPositions.isEmpty()) return        // Kristal slot'unu bir kez hazırla        val prepared = prepareItemForUse(session) ?: return        var placed = 0        for ((pos, _) in topPositions) {            val blockPos = Vector3i.from(pos.first, pos.second, pos.third)            if (sendPlacementUseRaw(session, prepared, blockPos)) placed++        }        // Hotbar'ı yalnızca bir kez geri al        prepared.revertTo?.let {            InventoryUtil.sendHotbarSelect(session, it)            EntityTracker.selfHotbarSlot = it        }        if (placed > 0) lastPlaceMs = now    }    // ── Vanilla patlama hasarı simülasyonu ────────────────────────────────    private fun simulateExplosionDamage(cx: Float, cy: Float, cz: Float): ExplosionResult {        val diameter = EXPLOSION_SIZE * 2f        var selfDamage = 0f        var mostDamage = 0f        val selfDist = MathUtil.dist3(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY + 0.9f, EntityTracker.selfZ)        if (selfDist <= diameter) {            val exposure = exposureTo(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ)            selfDamage = explosionDamage(selfDist, diameter, exposure)        }        for (p in EntityTracker.getPlayers(diameter)) {            if (p.runtimeId == EntityTracker.selfRuntimeId) continue            val dist = MathUtil.dist3(cx, cy, cz, p.x, p.y + 0.9f, p.z)            if (dist > diameter) continue            val exposure = exposureTo(cx, cy, cz, p.x, p.y, p.z)            val dmg = explosionDamage(dist, diameter, exposure)            if (dmg > mostDamage) mostDamage = dmg        }        return ExplosionResult(mostDamage, selfDamage)    }    // Vanilla: impact = (1 - mesafe/çap) × exposure    //          hasar = (impact² + impact) / 2 × 7 × çap + 1    private fun explosionDamage(distance: Float, diameter: Float, exposure: Float): Float {        if (distance > diameter) return 0f        val impact = (1f - distance / diameter) * exposure        return (impact * impact + impact) / 2f * 7f * diameter + 1f    }    // 5 sample nokta → ray cast → blok engeli → exposure oranı    private fun exposureTo(cx: Float, cy: Float, cz: Float, tx: Float, ty: Float, tz: Float): Float {        if (!WorldBlockTracker.hasAnyTerrainData()) return 1f        val samples = arrayOf(            Triple(tx, ty + 0.1f, tz),            Triple(tx, ty + 0.9f, tz),            Triple(tx, ty + 1.6f, tz),            Triple(tx + 0.3f, ty + 0.9f, tz),            Triple(tx - 0.3f, ty + 0.9f, tz)        )        var clear = 0        for ((sx, sy, sz) in samples) {            if (!isRayBlocked(cx, cy, cz, sx, sy, sz)) clear++        }        return clear.toFloat() / samples.size    }    private fun isRayBlocked(x0: Float, y0: Float, z0: Float, x1: Float, y1: Float, z1: Float): Boolean {        val dist = MathUtil.dist3(x0, y0, z0, x1, y1, z1)        if (dist < 0.01f) return false        val steps = (dist * 2f).toInt().coerceIn(1, 40)        for (i in 1 until steps) {            val t = i.toFloat() / steps            val bx = floor(x0 + (x1 - x0) * t).toInt()            val by = floor(y0 + (y1 - y0) * t).toInt()            val bz = floor(z0 + (z1 - z0) * t).toInt()            val id = WorldBlockTracker.getBlockIdentifier(bx, by, bz) ?: continue            if (id !in NON_SOLID) return true        }        return false    }    // Menzil küpünde obsidian/bedrock + üstü boş olan zeminleri tara    private fun searchPlaceBase(): List<Triple<Int, Int, Int>> {        if (!WorldBlockTracker.hasAnyTerrainData()) return emptyList()        val r  = floor(range.value).toInt()        val cx = floor(EntityTracker.selfX).toInt()        val cy = floor(EntityTracker.selfY).toInt()        val cz = floor(EntityTracker.selfZ).toInt()        val bases = ArrayList<Triple<Int, Int, Int>>()        for (x in cx - r..cx + r) {            for (y in cy - r..cy + r) {                for (z in cz - r..cz + r) {                    val id = WorldBlockTracker.getBlockIdentifier(x, y, z) ?: continue                    if (id != "minecraft:obsidian" && id != "minecraft:bedrock") continue                    val above = WorldBlockTracker.getBlockIdentifier(x, y + 1, z)                    if (above != null && above !in NON_SOLID) continue                    bases.add(Triple(x, y, z))                }            }        }        return bases    }    // ── Paket göndericiler ────────────────────────────────────────────────    private fun explodeCrystal(session: RubidiumRelaySession, runtimeId: Long) {        PacketUtil.sendSwing(session)        PacketUtil.sendAttack(session, runtimeId)    }    private fun prepareItemForUse(session: RubidiumRelaySession): PreparedItem? {        // Elde kristal varsa direkt kullan        EntityTracker.getHeldItem()?.let { held ->            if (InventoryUtil.resolveIdentifier(held) == "minecraft:end_crystal" && held.count > 0) {                return PreparedItem(EntityTracker.selfHotbarSlot, held, null)            }        }        // Hotbar'ı tara        for (slot in 0..8) {            val item = EntityTracker.getInventoryItem(slot) ?: continue            if (item.count <= 0 || InventoryUtil.resolveIdentifier(item) != "minecraft:end_crystal") continue            if (slot == EntityTracker.selfHotbarSlot) return PreparedItem(slot, item, null)            val original = EntityTracker.selfHotbarSlot            InventoryUtil.sendHotbarSelect(session, slot)            EntityTracker.selfHotbarSlot = slot            return PreparedItem(slot, item, original)        }        return null    }    private fun sendPlacementUseRaw(session: RubidiumRelaySession, prepared: PreparedItem, blockPos: Vector3i): Boolean {        val targetId = if (WorldBlockTracker.hasAnyTerrainData()) {            WorldBlockTracker.getBlockIdentifier(blockPos.x, blockPos.y, blockPos.z) ?: "minecraft:obsidian"        } else {            "minecraft:obsidian"        }        // FIX: cache'te yoksa yerleştirme yapma.        // Önceki sürüm hardcoded runtimeId=49 kullanıyordu — Bedrock'ta her        // server'da farklı dinamik runtimeId atandığı için server silently        // reject ediyordu. Cache ilk tick'te doldurulduğu için burada        // always-hit bekliyoruz; miss olursa yanlış ID'den iyidir.        val blockDef = blockDefCache[targetId] ?: return false        val playerPos = Vector3f.from(EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ)        return try {            session.serverBound(InventoryTransactionPacket().apply {                transactionType          = InventoryTransactionType.ITEM_USE                actionType               = 0                this.blockPosition       = blockPos                blockFace                = 1                hotbarSlot               = prepared.slot                itemInHand               = prepared.item                playerPosition           = playerPos                clickPosition            = Vector3f.from(0.5f, 1.0f, 0.5f)                blockDefinition          = blockDef                triggerType              = ItemUseTransaction.TriggerType.PLAYER_INPUT                clientInteractPrediction = ItemUseTransaction.PredictedResult.SUCCESS                clientCooldownState      = 0            })            true        } catch (_: Exception) {            false        }    }    // ── Block definition cache ────────────────────────────────────────────    //    // FIX (ana güvenilirlik düzeltmesi): önceki sürüm getBlockDefinition()'u    // her placement çağrısında çalıştırıyordu — 20.000 iterasyonluk döngü    // Netty IO thread'ini bloke edip drop/desync'e yol açıyordu.    //    // Şimdi: onEnable sonrası ilk tick'te bir kez çalışır, palette'in    // tamamını blockDefCache'e yükler. Sonraki tüm getBlockDefinition    // sorguları ConcurrentHashMap::get ile O(1) döner.    private fun ensureBlockCacheWarmed(session: RubidiumRelaySession) {        try {            val blockDefs = session.clientSession.peer.codecHelper.blockDefinitions ?: return            var i = 0            var misses = 0            while (i < 20000 && misses < 128) {                val def = try { blockDefs.getDefinition(i) } catch (_: Exception) { null }                if (def == null) { misses++; i++; continue }                misses = 0                val id = (def as? SimpleBlockDefinition)?.identifier                if (id != null) blockDefCache[id] = def                i++            }        } catch (_: Exception) {}    }}